/**
 * ボートレース予想ダッシュボードのルートコンポーネント。
 *
 * 日付・開催場・レースを選ぶと、出走表 / 直前情報 / 結果 を
 * BoatraceOpenAPI から取得して表示する。
 * オッズは公式サイト（boatrace.jp）からサーバー経由で自動取得する。
 * 選手の節間成績・過去走は、選手名クリックのたびに BoatraceOpenAPI
 * から直接まとめて取得し直す（端末には保存しない）。
 */

import React, { useEffect, useMemo, useState } from "react";
import { ClipboardList, Timer, Flag, Coins } from "lucide-react";

import "./boatrace.css";

import RaceSelector from "./components/RaceSelector.jsx";
import ProgramsTable from "./components/ProgramsTable.jsx";
import PreviewsPanel from "./components/PreviewsPanel.jsx";
import ResultsPanel from "./components/ResultsPanel.jsx";
import OddsPanel from "./components/OddsPanel.jsx";
import RacerStatsModal from "./components/RacerStatsModal.jsx";
import { Notice, Spinner } from "./components/ui.jsx";

import { fetchDaily, findRacesArray, findBoatsArray, selectRace, F, ymdOf } from "./lib/api.js";
import { normalizeGrade } from "./lib/aggregate.js";
import { API_START } from "./constants.js";

const TABS = [
  { key: "programs", label: "出走表", icon: ClipboardList },
  { key: "previews", label: "直前", icon: Timer },
  { key: "results", label: "結果", icon: Flag },
  { key: "odds", label: "オッズ", icon: Coins },
];

const EMPTY_DAILY = { programs: null, previews: null, results: null };

export default function BoatraceApp() {
  const [date, setDate] = useState(() => new Date());
  const [daily, setDaily] = useState(EMPTY_DAILY);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [stadium, setStadium] = useState(null);
  const [raceNo, setRaceNo] = useState(null);
  const [tab, setTab] = useState("programs");
  const [racer, setRacer] = useState(null);

  const [reloadKey, setReloadKey] = useState(0);

  const ymd = ymdOf(date);

  /* ---------------------------- 日次データの取得 ---------------------------- */

  useEffect(() => {
    const ac = new AbortController();
    let alive = true;

    (async () => {
      setLoading(true);
      setError(null);
      // 未公開・非開催は 404 になるので、種別ごとに握りつぶして null にする
      const get = async (kind) => {
        try {
          return await fetchDaily(kind, date, { signal: ac.signal });
        } catch (e) {
          if (e?.name === "AbortError") throw e;
          return null;
        }
      };

      try {
        const [programs, previews, results] = await Promise.all([
          get("programs"),
          get("previews"),
          get("results"),
        ]);
        if (!alive) return;
        setDaily({ programs, previews, results });
        if (!programs) setError("この日の出走表データが見つかりませんでした（非開催日、または未公開です）。");
      } catch (e) {
        if (alive && e?.name !== "AbortError") setError(String(e?.message || e));
      } finally {
        if (alive) setLoading(false);
      }
    })();

    return () => {
      alive = false;
      ac.abort();
    };
  }, [date, reloadKey]);

  /* ---------------------------- 選択肢の組み立て ---------------------------- */

  const programRaces = useMemo(() => findRacesArray(daily.programs), [daily.programs]);

  const stadiums = useMemo(() => {
    const set = new Set();
    for (const r of programRaces) {
      const no = F.stadium(r);
      if (no) set.add(no);
    }
    return set;
  }, [programRaces]);

  const gradeByStadium = useMemo(() => {
    const map = {};
    for (const r of programRaces) {
      const no = F.stadium(r);
      if (!no || map[no]) continue;
      map[no] = normalizeGrade(F.raceGrade(r), F.raceTitle(r));
    }
    return map;
  }, [programRaces]);

  const races = useMemo(() => {
    const list = programRaces
      .filter((r) => F.stadium(r) === Number(stadium))
      .map((r) => F.raceNo(r))
      .filter((n) => Number.isFinite(n));
    return [...new Set(list)].sort((a, b) => a - b);
  }, [programRaces, stadium]);

  const titleByRaceNo = useMemo(() => {
    const map = {};
    for (const r of programRaces) {
      if (F.stadium(r) !== Number(stadium)) continue;
      map[F.raceNo(r)] = F.raceSubtitle(r) || "";
    }
    return map;
  }, [programRaces, stadium]);

  /* ---------------------------- 開催場ごとの次回締切 ---------------------------- */

  // 締切時刻表示を生かしておくため、一定間隔で「現在時刻」を更新する
  const [now, setNow] = useState(() => new Date());
  useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 30000);
    return () => clearInterval(t);
  }, []);

  const nextCloseByStadium = useMemo(() => {
    const map = {};
    for (const no of stadiums) {
      let best = null;
      for (const r of programRaces) {
        if (F.stadium(r) !== no) continue;
        const raw = F.closedAt(r);
        if (!raw) continue;
        const t = new Date(String(raw).replace(" ", "T"));
        if (Number.isNaN(t.getTime()) || t <= now) continue;
        if (!best || t < best.time) best = { time: t, raceNo: F.raceNo(r) };
      }
      map[no] = best;
    }
    return map;
  }, [programRaces, stadiums, now]);

  // 開催場・レースの自動選択（日付を変えたときに不整合にならないように）
  useEffect(() => {
    if (!stadiums.size) {
      setStadium(null);
      return;
    }
    setStadium((prev) => (prev && stadiums.has(prev) ? prev : [...stadiums].sort((a, b) => a - b)[0]));
  }, [stadiums]);

  useEffect(() => {
    if (!races.length) {
      setRaceNo(null);
      return;
    }
    setRaceNo((prev) => (prev && races.includes(prev) ? prev : races[0]));
  }, [races]);

  /* ---------------------------- 表示対象のレース ---------------------------- */

  const programRace = useMemo(
    () => (stadium && raceNo ? selectRace(daily.programs, stadium, raceNo) : null),
    [daily.programs, stadium, raceNo]
  );
  const previewRace = useMemo(
    () => (stadium && raceNo ? selectRace(daily.previews, stadium, raceNo) : null),
    [daily.previews, stadium, raceNo]
  );
  const resultRace = useMemo(
    () => (stadium && raceNo ? selectRace(daily.results, stadium, raceNo) : null),
    [daily.results, stadium, raceNo]
  );

  const boatNames = useMemo(
    () => findBoatsArray(programRace).map((b) => F.racerName(b) ?? ""),
    [programRace]
  );

  /* ---------------------------- 描画 ---------------------------- */

  const outOfRange = date < API_START;

  return (
    <div className="boatrace-root">
      <RaceSelector
        date={date}
        onDateChange={setDate}
        loading={loading}
        onReload={() => setReloadKey((k) => k + 1)}
        stadiums={stadiums}
        stadium={stadium}
        onStadiumChange={setStadium}
        races={races}
        raceNo={raceNo}
        onRaceChange={setRaceNo}
        gradeByStadium={gradeByStadium}
        titleByRaceNo={titleByRaceNo}
        nextCloseByStadium={nextCloseByStadium}
      />

      <nav className="px-4 mt-4">
        <div className="flex gap-1.5 scroll-x pb-1 -mx-1 px-1">
          {TABS.map((t) => {
            const Icon = t.icon;
            const active = tab === t.key;
            return (
              <button
                key={t.key}
                onClick={() => setTab(t.key)}
                className={
                  "shrink-0 flex items-center gap-1 px-2.5 py-1.5 rounded-md text-xs font-medium border transition-colors " +
                  (active ? "bg-accent border-accent text-base" : "bg-panel border-line text-sub hover:border-accent")
                }
              >
                <Icon size={12} />
                {t.label}
              </button>
            );
          })}
        </div>
      </nav>

      <main className="px-4 mt-3">
        {outOfRange && (
          <div className="mb-3">
            <Notice tone="warn">
              対応期間外の日付です。データは2026年1月1日以降のみ取得できます。
            </Notice>
          </div>
        )}

        {error && tab !== "odds" && (
          <div className="mb-3">
            <Notice tone="warn">{error}</Notice>
          </div>
        )}

        {loading && tab !== "odds" ? (
          <Spinner label="データを取得中…" />
        ) : (
          <>
            {tab === "programs" && (
              <ProgramsTable
                race={programRace}
                grade={stadium ? gradeByStadium[stadium] : null}
                onOpenRacer={setRacer}
                stadium={stadium}
                date={date}
              />
            )}
            {tab === "previews" && (
              <PreviewsPanel race={previewRace} boatNames={boatNames} stadium={stadium} raceNo={raceNo} ymd={ymd} />
            )}
            {tab === "results" && <ResultsPanel race={resultRace} boatNames={boatNames} />}
            {tab === "odds" && (
              <OddsPanel
                boatNames={boatNames}
                stadium={stadium}
                raceNo={raceNo}
                ymd={ymd}
              />
            )}
          </>
        )}
      </main>

      {racer && (
        <RacerStatsModal
          racer={racer}
          stadium={stadium}
          ymd={ymd}
          onClose={() => setRacer(null)}
        />
      )}
    </div>
  );
}
