import React, { useEffect, useMemo, useState } from "react";
import { Calculator, ClipboardPaste, Trash, RefreshCw, Loader2 } from "lucide-react";
import { BET_TYPES, comboKey, syntheticOdds, oddsBandColor, ODDS_BANDS, parseOddsText } from "../lib/odds.js";
import { PROXY_BASE } from "../lib/api.js";
import { LaneBadge, Notice } from "./ui.jsx";

/**
 * オッズ画面。
 *
 * オッズタブを開いたとき、および開催場・レース・日付が変わったときに、
 * 取得用プロキシ（lib/api.js の PROXY_BASE。既定はローカルの
 * uipath-server=http://localhost:5001、.env で REACT_APP_PROXY_BASE を
 * 設定すればデプロイした cf-worker）経由で公式サイト（boatrace.jp）の
 * 単勝・複勝・拡連複・2連単・2連複・3連単・3連複オッズをまとめて自動取得する。
 * ブラウザから公式サイトを直接fetchするとCORSで拒否されるため、
 * プロキシを1枚挟んでいる。プロキシが動いていない/公式サイトのボット対策で
 * ブロックされた場合は失敗するので、その場合は「再取得」を試すか、
 * 手入力・貼り付けを使う。
 *
 * 「閲覧」時は、配信のオッズ映像のような一覧（人気順・大きな数字）で表示する。
 * 行をタップすると選択でき、複数選択すると下の「合成オッズ」に反映される。
 * 「入力中」に切り替えると、従来のマス目編集（手入力・貼り付け）に戻る。
 *
 * 複勝・拡連複はオッズに幅があるため、内部的には下限値を数値として保持し
 * （色分け・並び替え・合成オッズ計算のため）、実際の幅は別途注記として表示する。
 */

function lowerBoundOf(v) {
  if (typeof v === "number") return v;
  const m = String(v ?? "").match(/^([\d.]+)/);
  return m ? Number(m[1]) : NaN;
}

function Cell({ value, selected, onSelect, onChange, editing }) {
  const c = oddsBandColor(value);
  if (editing) {
    return (
      <td className="p-0 border border-base">
        <input
          value={Number.isFinite(value) ? value : ""}
          onChange={(e) => onChange(e.target.value)}
          inputMode="decimal"
          placeholder="―"
          className="w-12 h-9 text-center text-[10px] tabular-nums bg-panel text-ink outline-none focus:bg-line"
        />
      </td>
    );
  }
  return (
    <td
      onClick={onSelect}
      className={"w-12 h-9 text-center cursor-pointer border " + (selected ? "border-accent border-2" : "border-base")}
      style={{ background: c.bg }}
    >
      <span className="text-[10px] font-bold tabular-nums" style={{ color: c.fg }}>
        {Number.isFinite(value) ? value.toFixed(1) : "―"}
      </span>
    </td>
  );
}

function Matrix({ type, odds, setOdds, selected, toggle, editing }) {
  const def = BET_TYPES[type];
  const lanes = [1, 2, 3, 4, 5, 6];
  const [axis, setAxis] = useState(1);
  const isTriple = def.size === 3;
  const rows = isTriple ? lanes.filter((n) => n !== axis) : lanes;
  const cols = rows;

  const setVal = (key, raw) => {
    const n = Number(raw);
    setOdds((prev) => ({ ...prev, [key]: raw === "" ? undefined : n }));
  };

  return (
    <div>
      {isTriple && (
        <div className="flex items-center gap-1.5 mb-2">
          <span className="text-[10px] text-sub2">軸</span>
          {lanes.map((a) => (
            <button key={a} onClick={() => setAxis(a)} className={axis === a ? "ring-2 ring-accent rounded-md" : ""}>
              <LaneBadge lane={a} size="sm" />
            </button>
          ))}
          <span className="text-[10px] text-weak ml-1">{def.ordered ? "が1着" : "を含む"}</span>
        </div>
      )}
      <div className="scroll-x">
        <table className="border-collapse mx-auto">
          <thead>
            <tr>
              <th className="w-6 h-6" />
              {cols.map((c) => <th key={c} className="pb-1"><LaneBadge lane={c} size="xs" /></th>)}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row}>
                <th className="pr-1"><LaneBadge lane={row} size="xs" /></th>
                {cols.map((col) => {
                  const blocked = row === col || (!def.ordered && row > col);
                  if (blocked) return <td key={col} className="w-12 h-9 text-center text-[#2A3F52] text-[10px]">・</td>;
                  const combo = isTriple ? [axis, row, col] : [row, col];
                  if (new Set(combo).size !== combo.length) {
                    return <td key={col} className="w-12 h-9 text-center text-[#2A3F52] text-[10px]">・</td>;
                  }
                  const key = comboKey(type, combo);
                  return (
                    <Cell
                      key={col}
                      value={odds[key]}
                      selected={selected.has(key)}
                      onSelect={() => toggle(key)}
                      onChange={(v) => setVal(key, v)}
                      editing={editing}
                    />
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="text-[9px] text-weak text-center mt-1">
        {isTriple
          ? (def.ordered ? "縦=2着 / 横=3着" : "残り2艇（順不同）")
          : (def.ordered ? "縦=1着 / 横=2着" : "組み合わせ（順不同）")}
      </div>
    </div>
  );
}

function SingleTable({ boats, odds, setOdds, selected, toggle, editing, type }) {
  return (
    <table className="w-full text-xs border-collapse">
      <thead>
        <tr className="text-sub2 border-b border-line">
          <th className="text-left font-normal py-1.5 pl-1">枠</th>
          <th className="text-left font-normal py-1.5">選手</th>
          <th className="text-right font-normal py-1.5 pr-1">{BET_TYPES[type].label}オッズ</th>
        </tr>
      </thead>
      <tbody>
        {[1, 2, 3, 4, 5, 6].map((lane) => {
          const key = String(lane);
          const v = odds[key];
          const c = oddsBandColor(v);
          const name = boats?.[lane - 1] ?? "";
          return (
            <tr key={lane} className="border-b border-line last:border-b-0">
              <td className="py-1.5 pl-1"><LaneBadge lane={lane} size="sm" /></td>
              <td className="py-1.5 text-ink truncate max-w-[8rem]">{name}</td>
              <td className="py-1.5 pr-1 text-right">
                {editing ? (
                  <input
                    value={Number.isFinite(v) ? v : ""}
                    onChange={(e) => setOdds((p) => ({ ...p, [key]: e.target.value === "" ? undefined : Number(e.target.value) }))}
                    inputMode="decimal"
                    placeholder="―"
                    className="w-16 text-right text-xs tabular-nums bg-base border border-line rounded px-1.5 py-0.5 text-ink outline-none focus:border-accent"
                  />
                ) : (
                  <button onClick={() => toggle(key)} style={{ background: c.bg, color: c.fg }}
                    className={"px-2 py-0.5 rounded font-bold tabular-nums " + (selected.has(key) ? "ring-2 ring-accent" : "")}>
                    {Number.isFinite(v) ? v.toFixed(1) : "―"}
                  </button>
                )}
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

/**
 * 配信のオッズ映像のような一覧表示。
 * オッズが低い順（人気が高い順）に並べ、行をタップすると選択できる。
 */
function OddsBoard({ type, odds, boatNames, selected, toggle }) {
  const def = BET_TYPES[type];
  const isRange = type === "place" || type === "quinella_place";

  const rows = useMemo(() => {
    const entries = Object.entries(odds).filter(([, v]) => v !== undefined && v !== null && v !== "");
    const withSort = entries.map(([key, v]) => ({
      key,
      v,
      sortVal: isRange ? lowerBoundOf(v) : Number(v),
      lanes: key.split("-").map(Number),
    }));
    withSort.sort((a, b) => {
      const av = Number.isFinite(a.sortVal) ? a.sortVal : Infinity;
      const bv = Number.isFinite(b.sortVal) ? b.sortVal : Infinity;
      return av - bv;
    });
    return withSort;
  }, [odds, isRange]);

  return (
    <div className="br-board">
      <div className="br-board-head">
        <span className="br-board-title">{def.label}オッズ</span>
        <span className="text-[10px] text-sub2">{rows.length}点</span>
      </div>
      <div className="br-board-rows">
        {!rows.length && <div className="text-[11px] text-weak text-center py-8">まだ取得していません。「再取得」を試すか、手入力してください。</div>}
        {rows.map((r, i) => (
          <button
            key={r.key}
            onClick={() => toggle(r.key)}
            className={"br-board-row" + (i === 0 ? " is-fav" : "") + (selected.has(r.key) ? " is-selected" : "")}
          >
            <span className="br-board-rank">{i + 1}<span className="br-board-rank-unit">番人気</span></span>
            <span className="br-board-lane">
              {r.lanes.map((ln, li) => (
                <React.Fragment key={li}>
                  {li > 0 && <span className="br-board-sep">{def.ordered ? "→" : "―"}</span>}
                  <LaneBadge lane={ln} size="sm" />
                </React.Fragment>
              ))}
            </span>
            {def.size === 1 && <span className="br-board-name">{boatNames?.[r.lanes[0] - 1] || ""}</span>}
            <span className="br-board-odds">
              {isRange ? String(r.v) : Number.isFinite(Number(r.v)) ? Number(r.v).toFixed(1) : String(r.v)}
              <span className="br-board-odds-unit">倍</span>
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

const LANES = [1, 2, 3, 4, 5, 6];

/**
 * 3連単専用の一覧。公式サイトの見た目（軸ごとに列がある表）を踏襲しつつ、
 * 軸＝1着艇ごとに「選手名」を見出しとして出し、2着候補ごとに
 *   - その2連単オッズ（実際の売買オッズ）
 *   - 残り1艇ぶんの3連単オッズをすべて合成した場合のオッズ（参考値）
 * を並べて比較できるようにする。合成オッズが2連単の実オッズより低ければ
 * （＝3連単を割ったほうが得られる配当が小さければ）2連単の方が有利、
 * 逆に高ければ3連単を割ったほうが有利……という目安になる。
 * その下に、内訳となる3連単オッズ（2着×3着）をそのまま並べる。
 */
function TrifectaBoard({ boatNames, trifectaOdds, exactaOdds, selected, toggle }) {
  return (
    <div className="space-y-3">
      {LANES.map((axis) => {
        const seconds = LANES.filter((n) => n !== axis);
        return (
          <div key={axis}>
            <div className="flex items-center gap-1.5 mb-1.5">
              <LaneBadge lane={axis} size="sm" />
              <span className="text-xs font-semibold text-ink truncate">{boatNames?.[axis - 1] || ""}</span>
            </div>
            <div className="space-y-2">
              {seconds.map((second) => {
                const exactaKey = comboKey("exacta", [axis, second]);
                const exOdds = exactaOdds[exactaKey];
                const thirds = LANES.filter((n) => n !== axis && n !== second);
                const triOddsList = thirds
                  .map((third) => trifectaOdds[comboKey("trifecta", [axis, second, third])])
                  .filter((v) => Number.isFinite(v));
                const synth = syntheticOdds(triOddsList);

                return (
                  <div key={second} className="bg-base border border-line rounded-lg p-2">
                    <div className="flex items-center justify-between">
                      <span className="flex items-center gap-1 text-xs font-semibold text-ink">
                        <LaneBadge lane={axis} size="xs" />→<LaneBadge lane={second} size="xs" />
                        <span className="text-[9px] text-weak font-normal ml-1">2連単</span>
                      </span>
                      <span className="text-right leading-tight">
                        <div className="text-sm font-bold tabular-nums text-ink">
                          {Number.isFinite(exOdds) ? exOdds.toFixed(1) : "―"}倍
                        </div>
                        <div className="text-[10px] text-sub2 tabular-nums">
                          {synth ? `${synth.toFixed(2)}倍(合成オッズ)` : "―(合成オッズ)"}
                        </div>
                      </span>
                    </div>
                    <div className="text-[8px] text-weak mt-1 mb-1">以下は通常の3連単オッズ</div>
                    <div className="grid grid-cols-4 gap-1">
                      {thirds.map((third) => {
                        const key = comboKey("trifecta", [axis, second, third]);
                        const v = trifectaOdds[key];
                        const c = oddsBandColor(v);
                        return (
                          <button
                            key={third}
                            onClick={() => toggle(key)}
                            style={{ background: c.bg, color: c.fg }}
                            className={"rounded px-1 py-1 text-center " + (selected.has(key) ? "ring-2 ring-accent" : "")}
                          >
                            <div className="flex items-center justify-center"><LaneBadge lane={third} size="xs" /></div>
                            <div className="text-[10px] font-bold tabular-nums mt-0.5">
                              {Number.isFinite(v) ? v.toFixed(1) : "―"}
                            </div>
                          </button>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
}

export default function OddsPanel({ boatNames, stadium, raceNo, ymd }) {
  const [category, setCategory] = useState("sanren");
  const [singleSub, setSingleSub] = useState("win");
  const [nirenSub, setNirenSub] = useState("exacta");
  const [sanrenSub, setSanrenSub] = useState("trifecta");
  const [editing, setEditing] = useState(false);
  const [pasteOpen, setPasteOpen] = useState(false);
  const [pasteText, setPasteText] = useState("");
  // odds[betType][comboKey] = number（複勝・拡連複は下限値の数値。実際の幅は rangeText 参照）
  const [allOdds, setAllOdds] = useState({});
  const [rangeText, setRangeText] = useState({}); // { place: "1: 1.3-1.5　2: ...", quinella_place: "..." }
  const [selected, setSelected] = useState(() => new Set());

  const [autoLoading, setAutoLoading] = useState(false);
  const [autoError, setAutoError] = useState(null);
  const [autoWarnings, setAutoWarnings] = useState([]);

  const canAutoFetch = Boolean(stadium && raceNo && ymd);

  const fetchAutoOdds = async () => {
    if (!canAutoFetch) return;
    setAutoLoading(true);
    setAutoError(null);
    setAutoWarnings([]);
    try {
      const url = `${PROXY_BASE}/api/odds/all?stadium=${stadium}&hd=${ymd}&rno=${raceNo}`;
      const res = await fetch(url);
      const data = await res.json().catch(() => null);
      if (!res.ok) throw new Error(data?.error || `HTTP ${res.status}`);
      if (!data) throw new Error("応答を解釈できませんでした");
      if (data.noData) {
        setAutoError("公式サイトにまだオッズが出ていません（発売前・締切直後などの可能性があります）。");
        return;
      }

      const next = {};
      const nextRangeText = {};

      if (data.win) next.win = Object.fromEntries(Object.entries(data.win).filter(([, v]) => Number.isFinite(v)));
      if (data.place) {
        const entries = Object.entries(data.place).filter(([, v]) => v);
        next.place = Object.fromEntries(entries.map(([lane, range]) => [lane, lowerBoundOf(range)]));
        if (entries.length) nextRangeText.place = entries.map(([lane, range]) => `${lane}: ${range}`).join("　");
      }
      for (const type of ["exacta", "quinella", "trifecta", "trio"]) {
        if (data[type]) next[type] = Object.fromEntries(Object.entries(data[type]).filter(([, v]) => Number.isFinite(v)));
      }
      if (data.quinella_place) {
        const entries = Object.entries(data.quinella_place).filter(([, v]) => v);
        next.quinella_place = Object.fromEntries(entries.map(([k, range]) => [k, lowerBoundOf(range)]));
        if (entries.length) nextRangeText.quinella_place = entries.map(([k, range]) => `${k}: ${range}`).join("　");
      }

      setAllOdds((prev) => {
        const merged = { ...prev };
        for (const [type, vals] of Object.entries(next)) merged[type] = { ...(merged[type] || {}), ...vals };
        return merged;
      });
      setRangeText((prev) => ({ ...prev, ...nextRangeText }));

      const gotAny = Object.values(next).some((o) => Object.keys(o).length > 0);
      const failedPages = Object.entries(data.errors || {}).map(([page, e]) => `${page}: ${e.error}`);
      if (!gotAny) {
        setAutoError("取得はできましたが、数値を読み取れませんでした。ページ構成が変わった可能性があります。");
      } else if (failedPages.length) {
        setAutoWarnings(failedPages);
      }
    } catch (e) {
      setAutoError(
        `取得できませんでした（${String(e.message || e)}）。取得用プロキシ（ローカルなら uipath-server を node index.js で起動、または .env の REACT_APP_PROXY_BASE でデプロイ済みのプロキシを指定）を確認してください。ブロックされている場合は手入力・貼り付けを使ってください。`
      );
    } finally {
      setAutoLoading(false);
    }
  };

  // オッズタブを開いたとき、および開催場・レース・日付が変わったときに自動取得する
  useEffect(() => {
    setAllOdds({});
    setRangeText({});
    setSelected(new Set());
    setAutoError(null);
    setAutoWarnings([]);
    if (stadium && raceNo && ymd) fetchAutoOdds();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stadium, raceNo, ymd]);

  const type = category === "single" ? singleSub : category === "niren" ? nirenSub : sanrenSub;
  const odds = allOdds[type] || {};
  const setOdds = (updater) =>
    setAllOdds((prev) => ({ ...prev, [type]: typeof updater === "function" ? updater(prev[type] || {}) : updater }));

  const toggle = (key) =>
    setSelected((prev) => {
      const n = new Set(prev);
      n.has(key) ? n.delete(key) : n.add(key);
      return n;
    });

  const switchTo = (setter, val) => { setter(val); setSelected(new Set()); };

  const selectedOdds = useMemo(
    () => [...selected].map((k) => odds[k]).filter((v) => Number.isFinite(v) && v > 0),
    [selected, odds]
  );
  const synth = syntheticOdds(selectedOdds);

  const applyPaste = () => {
    const parsed = parseOddsText(pasteText, type);
    const count = Object.keys(parsed).length;
    if (count) setOdds((prev) => ({ ...prev, ...parsed }));
    setPasteText("");
    setPasteOpen(false);
  };

  const clearType = () => { setOdds({}); setSelected(new Set()); };

  return (
    <div>
      <Notice tone="warn">
        オッズと投票数はBoatraceOpenAPIに含まれないため、オッズタブを開くと取得用プロキシ経由で公式サイトから自動取得します。公式サイトのボット対策でブロックされる場合や、プロキシが動いていない場合は失敗するので、その場合は「再取得」を試すか「入力中」に切り替えて手入力・貼り付けを使ってください。複勝・拡連複はオッズに幅があるため、一覧には下限値を表示しています（幅そのものは下の注記を参照）。
      </Notice>

      <div className="mt-3 flex items-center gap-2">
        <div className="flex-1 min-w-0 text-[11px]">
          {!canAutoFetch ? (
            <span className="text-weak">開催場・レースが選択されていないため自動取得できません。</span>
          ) : autoLoading ? (
            <span className="flex items-center gap-1.5 text-sub2"><Loader2 size={12} className="animate-spin" />公式サイトから取得中…</span>
          ) : autoError ? (
            <span className="text-[#E5433D] leading-relaxed">{autoError}</span>
          ) : (
            <span className="text-sub2">公式サイトから自動取得済み</span>
          )}
          {!!autoWarnings.length && (
            <div className="text-amber leading-relaxed mt-0.5">
              一部のページは取得できませんでした：{autoWarnings.join("　")}
            </div>
          )}
        </div>
        <button
          onClick={fetchAutoOdds}
          disabled={!canAutoFetch || autoLoading}
          className="shrink-0 flex items-center gap-1 text-[11px] font-semibold bg-panel border border-line text-sub px-2.5 py-1.5 rounded-md disabled:opacity-50 hover:border-accent"
        >
          <RefreshCw size={12} className={autoLoading ? "animate-spin" : ""} />再取得
        </button>
      </div>

      <div className="flex gap-1 mt-3">
        {[{ k: "single", l: "単複・拡連複" }, { k: "niren", l: "2連系" }, { k: "sanren", l: "3連系" }].map((c) => (
          <button key={c.k} onClick={() => { setCategory(c.k); setSelected(new Set()); }}
            className={"flex-1 py-1.5 rounded-md text-xs font-semibold border transition-colors " +
              (category === c.k ? "bg-accent border-accent text-base" : "bg-panel border-line text-sub")}>
            {c.l}
          </button>
        ))}
      </div>

      <div className="flex items-center gap-1 mt-2 flex-wrap">
        {category === "single" && [{ k: "win", l: "単勝" }, { k: "place", l: "複勝" }, { k: "quinella_place", l: "拡連複" }].map((s) => (
          <button key={s.k} onClick={() => switchTo(setSingleSub, s.k)}
            className={"px-2.5 py-1 rounded text-[11px] font-semibold border " +
              (singleSub === s.k ? "bg-amber border-amber text-base" : "bg-panel border-line text-sub")}>{s.l}</button>
        ))}
        {category === "niren" && [{ k: "exacta", l: "2連単" }, { k: "quinella", l: "2連複" }].map((s) => (
          <button key={s.k} onClick={() => switchTo(setNirenSub, s.k)}
            className={"px-2.5 py-1 rounded text-[11px] font-semibold border " +
              (nirenSub === s.k ? "bg-amber border-amber text-base" : "bg-panel border-line text-sub")}>{s.l}</button>
        ))}
        {category === "sanren" && [{ k: "trifecta", l: "3連単" }, { k: "trio", l: "3連複" }].map((s) => (
          <button key={s.k} onClick={() => switchTo(setSanrenSub, s.k)}
            className={"px-2.5 py-1 rounded text-[11px] font-semibold border " +
              (sanrenSub === s.k ? "bg-amber border-amber text-base" : "bg-panel border-line text-sub")}>{s.l}</button>
        ))}

        <div className="ml-auto flex items-center gap-1">
          <button onClick={() => setEditing((e) => !e)}
            className={"px-2 py-1 rounded text-[10px] font-semibold border " +
              (editing ? "bg-accent border-accent text-base" : "bg-panel border-line text-sub")}>
            {editing ? "入力中" : "閲覧"}
          </button>
          <button onClick={() => setPasteOpen((o) => !o)} className="p-1.5 rounded border border-line bg-panel text-sub2 hover:text-accent" aria-label="一括入力">
            <ClipboardPaste size={13} />
          </button>
          <button onClick={clearType} className="p-1.5 rounded border border-line bg-panel text-sub2 hover:text-[#E5433D]" aria-label="この式別をクリア">
            <Trash size={13} />
          </button>
        </div>
      </div>

      {pasteOpen && (
        <div className="mt-2 bg-panel border border-line rounded-lg p-2.5">
          <div className="text-[10px] text-sub2 mb-1.5">
            1行につき「組番 オッズ」の形式で貼り付けます（例：1-2-3 6.8）。現在選択中の「{BET_TYPES[type].label}」に取り込みます。
          </div>
          <textarea
            value={pasteText}
            onChange={(e) => setPasteText(e.target.value)}
            rows={5}
            placeholder={"1-2-3 6.8\n1-3-2 9.4\n1-2-4 12.1"}
            className="w-full bg-base border border-line rounded p-2 text-xs text-ink tabular-nums outline-none focus:border-accent"
          />
          <button onClick={applyPaste} className="mt-1.5 text-xs font-semibold bg-accent text-base px-3 py-1.5 rounded-md">取り込む</button>
        </div>
      )}

      <div className="mt-3">
        <div className="min-w-0">
          <div className="bg-panel border border-line rounded-lg p-2.5">
            {editing ? (
              category === "single" ? (
                <SingleTable boats={boatNames} odds={odds} setOdds={setOdds} selected={selected} toggle={toggle} editing={editing} type={singleSub} />
              ) : (
                <>
                  <Matrix type={type} odds={odds} setOdds={setOdds} selected={selected} toggle={toggle} editing={editing} />
                  <div className="flex flex-wrap gap-x-2 gap-y-1 mt-1.5">
                    {ODDS_BANDS.map(([l, c]) => (
                      <span key={l} className="flex items-center gap-1 text-[9px] text-sub2">
                        <span className="w-2.5 h-2.5 rounded-sm" style={{ background: c }} />{l}倍
                      </span>
                    ))}
                  </div>
                </>
              )
            ) : type === "trifecta" ? (
              <TrifectaBoard
                boatNames={boatNames}
                trifectaOdds={odds}
                exactaOdds={allOdds.exacta || {}}
                selected={selected}
                toggle={toggle}
              />
            ) : (
              <OddsBoard type={type} odds={odds} boatNames={boatNames} selected={selected} toggle={toggle} />
            )}
          </div>

          {rangeText[type] && (
            <div className="text-[10px] text-sub2 mt-1.5 leading-relaxed">
              幅のある表示（参考）：{rangeText[type]}
            </div>
          )}

          <div className="mt-3 bg-panel border border-line rounded-lg p-3">
            <div className="flex items-center gap-1.5 text-xs font-semibold text-ink mb-2">
              <Calculator size={13} className="text-accent" />合成オッズ
            </div>
            <div className="flex items-center justify-between">
              <span className="text-xs text-sub2">{BET_TYPES[type].label}・{selectedOdds.length}点選択中</span>
              <span className="text-lg font-bold tabular-nums text-amber">{synth ? `${synth.toFixed(2)}倍` : "―"}</span>
            </div>
            {synth && (
              <div className="text-[10px] text-weak text-right mt-0.5">
                全点均等に計100円 → 的中時 約{(synth * 100).toFixed(0)}円
              </div>
            )}
            <div className="text-[10px] text-weak mt-2 leading-relaxed">
              オッズの行（またはマス）をタップすると選択できます。合成オッズ = 1 ÷ Σ(1 ÷ 各点のオッズ)。
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
